INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Dient das SMART-Prinzip der Zielformulierung?', 2, '[{"text": "Ja", "correct": true, "because": "Strukturiert Ziele"}, {"text": "Nein", "correct": false, "because": "Es ist dafür entwickelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal gehört zum SMART-Prinzip?', 3, '[{"text": "Realistisch", "correct": true, "because": "Ziele sollen machbar sein"}, {"text": "Unbestimmt", "correct": false, "because": "Widerspricht SMART"}, {"text": "Komplex", "correct": false, "because": "Nicht Teil der Definition"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) SMART-Ziele sind klar definiert. b) SMART-Ziele sind immer langfristig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) trifft zu"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente umfasst das SMART-Prinzip?', 4, '[{"text": "Messbar", "correct": true, "because": "Erfolg überprüfbar"}, {"text": "Vage", "correct": false, "because": "Widerspricht SMART"}, {"text": "Attraktiv", "correct": true, "because": "Motiviert Beteiligte"}, {"text": "Terminiert", "correct": true, "because": "Setzt Zeitrahmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Ziel ohne SMART-Prinzip effektiv sein?', 2, '[{"text": "Ja", "correct": true, "because": "Andere Methoden möglich"}, {"text": "Nein", "correct": false, "because": "SMART ist optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel entspricht nicht dem SMART-Prinzip?', 3, '[{"text": "Irgendwas bald tun", "correct": true, "because": "Zu ungenau"}, {"text": "Datenbank bis 15. April optimieren", "correct": false, "because": "SMART-konform"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das SMART-Prinzip nur für IT-Projekte geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Universell einsetzbar"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Nutzen bietet das SMART-Prinzip?', 3, '[{"text": "Erhöhte Zielgenauigkeit", "correct": true, "because": "Fördert Präzision"}, {"text": "Unklare Richtung", "correct": false, "because": "Widerspricht SMART"}, {"text": "Keine Struktur", "correct": false, "because": "Gibt Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) SMART fördert Planbarkeit. b) SMART-Ziele sind immer teuer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist unabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) trifft zu"}]'),
('00000000-0000-0000-0000-000000000000', 'Was fehlt bei "Projekt verbessern"?', 2, '[{"text": "SMART-Kriterien", "correct": true, "because": "Zu vage"}, {"text": "Budgetplan", "correct": false, "because": "Nicht Teil von SMART"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein SMART-Ziel mehrere Teilziele haben?', 2, '[{"text": "Ja", "correct": true, "because": "Wenn SMART erfüllt"}, {"text": "Nein", "correct": false, "because": "Flexibilität möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt ein SMART-Ziel?', 3, '[{"text": "10 Tickets bis Freitag lösen", "correct": true, "because": "Klar und terminiert"}, {"text": "Irgendwann besser werden", "correct": false, "because": "Nicht spezifisch"}, {"text": "Software optimieren", "correct": false, "because": "Zu ungenau"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das SMART-Prinzip immer zwingend?', 2, '[{"text": "Nein", "correct": true, "because": "Alternative Ansätze möglich"}, {"text": "Ja", "correct": false, "because": "Optional einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kriterien gehören nicht zum SMART-Prinzip?', 3, '[{"text": "Unbestimmt", "correct": true, "because": "Widerspricht SMART"}, {"text": "Spezifisch", "correct": false, "because": "Teil von SMART"}, {"text": "Messbar", "correct": false, "because": "Teil von SMART"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen SMART-Ziele immer schriftlich formuliert sein?', 2, '[{"text": "Nein", "correct": true, "because": "Klarheit reicht"}, {"text": "Ja", "correct": false, "because": "Form ist flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das SMART-Prinzip?', 3, '[{"text": "Ziele strukturiert definieren", "correct": true, "because": "Fördert Klarheit"}, {"text": "Kosten senken", "correct": false, "because": "Unabhängig davon"}, {"text": "Team vergrößern", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das SMART-Prinzip in der Initiierung genutzt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Hilft bei Zielsetzung"}, {"text": "Nein", "correct": false, "because": "Passend für Initiierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor macht "bessere Software" nicht SMART?', 3, '[{"text": "Fehlende Spezifität", "correct": true, "because": "Zu vage"}, {"text": "Klarer Nutzen", "correct": false, "because": "Nicht das Problem"}, {"text": "Teamgröße", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) SMART-Ziele sind zeitgebunden. b) SMART ignoriert Realität.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Realität zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Vorteil des SMART-Prinzips?', 3, '[{"text": "Erfolgsmessung ermöglichen", "correct": true, "because": "Fördert Kontrolle"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht SMART"}, {"text": "Keine Zeitvorgaben", "correct": false, "because": "Terminiert ist Teil"}]');